#!/usr/bin/env bash
#
# Stages one built binary into a release archive.
#
# The archive holds `skald` at its root plus whichever of README.md and the
# licence files exist in the tree. install.sh extracts to a temp directory and
# copies `skald` out, so the layout has to keep that name.
#
# macOS archives also carry `Skald.app`, built from the same binary by
# scripts/bundle.sh, so a downloaded release can be dragged into /Applications
# and shows the icon from media/skald.svg. `skald` stays at the archive root
# for install.sh.
#
# Environment:
#   VERSION  the version being released, without a leading v
#   TARGET   the rust target triple that was built
#   ASSET    the asset suffix, for example linux-x86_64
#
# Writes dist/skald-<version>-<asset>.tar.gz. Must run from the repository root,
# after `cargo build --release --target $TARGET`.

set -euo pipefail

staging=$(mktemp -d)
trap 'rm -rf "$staging"' EXIT

cp "target/$TARGET/release/skald" "$staging/skald"

for extra in README.md LICENSE LICENSE.md; do
    if [ -f "$extra" ]; then
        cp "$extra" "$staging/"
    fi
done

# A macOS .app is the only way the icon reaches the Dock. The bundle is built
# from the same release binary and staged next to the bare binary; the icns is
# regenerated by bundle.sh when the source SVG is newer, so no stale asset can
# be published.
if [ "$(uname -s)" = Darwin ]; then
    BINARY="target/$TARGET/release/skald" BUNDLE_DIR="$staging" scripts/bundle.sh
fi

mkdir -p dist
tar -czf "dist/skald-$VERSION-$ASSET.tar.gz" -C "$staging" .

echo "Packaged dist/skald-$VERSION-$ASSET.tar.gz"
